INSERT INTO INCIDENTE (id_incidente, codigo, titulo, descricao, data_ocorrencia, data_registro, id_origem_incidente, id_categoria_incidente, id_severidade, id_status_incidente, id_ativo, id_usuario, data_atualizacao, data_resolucao, data_encerramento) VALUES
(1, 'INC-00001', 'Quedas frequentes na VPN', 'A conexão VPN cai repetidamente durante o expediente. O incidente impactou a produtividade da equipe. O caso segue em acompanhamento pela equipe técnica.', '2026-04-01 00:00:00', '2026-04-01 01:01:00', 1, 3, 268, 183, 4, 1, '2026-04-02 01:01:00', NULL, NULL),
(2, 'INC-00002', 'Tela azul recorrente', 'O equipamento reinicia com tela azul repetidas vezes. Serviços dependentes apresentaram instabilidade. O incidente foi escalado para o nível seguinte de suporte.', '2026-04-02 00:37:00', '2026-04-02 01:09:00', 1, 1, 35, 365, 11, 2, '2026-04-02 11:09:00', NULL, NULL),
(3, 'INC-00003', 'Reinicialização inesperada de servidor', 'O servidor reiniciou sem janela de manutenção programada. Um grupo de usuários ficou sem acesso ao recurso. Aplicou-se uma solução de contorno enquanto a causa é investigada.', '2026-04-03 01:14:00', '2026-04-03 01:47:00', 5, 1, 282, 27, 3, 3, '2026-04-03 12:47:00', NULL, NULL),
(4, 'INC-00004', 'Impressora fora de rede', 'A impressora deixou de responder na rede e não recebe trabalhos. Houve risco de indisponibilidade prolongada do serviço. Foram coletados logs e evidências para análise.', '2026-04-04 01:51:00', '2026-04-04 02:25:00', 4, 6, 49, 221, 7, 4, '2026-04-04 20:25:00', '2026-04-04 20:25:00', NULL),
(5, 'INC-00005', 'Alto uso de sessões no firewall', 'O firewall atingiu o limite de sessões simultâneas. A ocorrência gerou aumento no volume de chamados. O chamado foi direcionado ao suporte responsável.', '2026-04-05 02:28:00', '2026-04-05 03:03:00', 5, 4, 316, 397, 4, 5, '2026-04-06 05:03:00', '2026-04-05 23:03:00', '2026-04-06 05:03:00'),
(6, 'INC-00006', 'Bloqueio de tabela por transação longa', 'Uma transação longa bloqueou operações de outros usuários. A operação do setor foi prejudicada durante o período. A equipe de TI iniciou o diagnóstico.', '2026-04-06 03:05:00', '2026-04-06 03:41:00', 1, 8, 63, 53, 2, 6, '2026-04-06 17:41:00', NULL, NULL),
(7, 'INC-00007', 'Queda do tronco telefônico', 'As ligações externas ficaram indisponíveis. O problema foi classificado conforme impacto e urgência. O caso segue em acompanhamento pela equipe técnica.', '2026-04-07 03:42:00', '2026-04-07 04:19:00', 3, 3, 330, 235, 5, 7, '2026-04-07 19:19:00', NULL, NULL),
(8, 'INC-00008', 'Wi-Fi instável em setor administrativo', 'O sinal sem fio cai com frequência na área administrativa. O atendimento a clientes internos foi parcialmente afetado. O incidente foi escalado para o nível seguinte de suporte.', '2026-04-08 04:19:00', '2026-04-08 04:57:00', 3, 3, 97, 417, 6, 8, '2026-04-08 20:57:00', NULL, NULL),
(9, 'INC-00009', 'Alerta de malware em estação de trabalho', 'O antivírus detectou arquivo malicioso em um equipamento. O incidente impactou a produtividade da equipe. Aplicou-se uma solução de contorno enquanto a causa é investigada.', '2026-04-09 04:56:00', '2026-04-09 05:35:00', 2, 4, 344, 96, 4, 9, '2026-04-10 09:35:00', '2026-04-10 09:35:00', NULL),
