(11, 'INC-00011', 'Falha de acesso ao compartilhamento de arquivos', 'Usuários não conseguiram acessar pastas da rede. Um grupo de usuários ficou sem acesso ao recurso. O chamado foi direcionado ao suporte responsável.', '2026-04-11 06:10:00', '2026-04-11 06:51:00', 2, 1, 378, 443, 3, 11, '2026-04-12 01:51:00', NULL, NULL),
(12, 'INC-00012', 'Falha na rotina de backup noturno', 'A rotina de backup não foi concluída dentro da janela prevista. Houve risco de indisponibilidade prolongada do serviço. A equipe de TI iniciou o diagnóstico.', '2026-04-12 06:47:00', '2026-04-12 07:29:00', 5, 2, 125, 105, 14, 12, '2026-04-13 03:29:00', NULL, NULL),
(13, 'INC-00013', 'Fila do service desk acima da capacidade', 'O volume de chamados superou a capacidade de atendimento. A ocorrência gerou aumento no volume de chamados. O caso segue em acompanhamento pela equipe técnica.', '2026-04-13 07:24:00', '2026-04-13 08:07:00', 4, 2, 392, 287, 9, 13, '2026-04-14 05:07:00', NULL, NULL),
