(456, 'INC-00456', 'Falha no nobreak da sala técnica', 'O nobreak apresentou alerta de bateria e autonomia reduzida. O atendimento a clientes internos foi parcialmente afetado. A equipe de TI iniciou o diagnóstico.', '2026-08-28 16:35:00', '2026-08-28 17:11:00', 1, 1, 73, 313, 1, 456, '2026-08-29 10:11:00', NULL, NULL),
(457, 'INC-00457', 'Indisponibilidade do repositório de código', 'O repositório ficou inacessível para a equipe de desenvolvimento. O incidente impactou a produtividade da equipe. O caso segue em acompanhamento pela equipe técnica.', '2026-08-29 17:12:00', '2026-08-29 17:49:00', 1, 2, 340, 495, 13, 457, '2026-08-30 11:49:00', NULL, NULL),
(458, 'INC-00458', 'Falha no envio de e-mails', 'Mensagens ficaram na fila de saída e não foram entregues. Serviços dependentes apresentaram instabilidade. O incidente foi escalado para o nível seguinte de suporte.', '2026-08-30 17:49:00', '2026-08-30 18:27:00', 3, 7, 87, 157, 13, 458, '2026-08-31 13:27:00', NULL, NULL),
(459, 'INC-00459', 'Erro de processamento em rotina agendada', 'A rotina agendada terminou com erro e não gerou o resultado. Um grupo de usuários ficou sem acesso ao recurso. Aplicou-se uma solução de contorno enquanto a causa é investigada.', '2026-08-31 18:26:00', '2026-08-31 19:05:00', 1, 2, 354, 346, 13, 459, '2026-09-02 00:05:00', '2026-09-02 00:05:00', NULL),
(460, 'INC-00460', 'Falha de comunicação entre filiais', 'Sistemas de filiais ficaram inacessíveis por instabilidade no link. Houve risco de indisponibilidade prolongada do serviço. Foram coletados logs e evidências para análise.', '2026-04-01 19:03:00', '2026-04-01 19:43:00', 2, 3, 101, 22, 5, 460, '2026-04-03 07:43:00', '2026-04-03 02:43:00', '2026-04-03 07:43:00'),
(461, 'INC-00461', 'Falha de conexão VPN', 'Colaboradores remotos não conseguiram estabelecer a conexão VPN. A ocorrência gerou aumento no volume de chamados. O chamado foi direcionado ao suporte responsável.', '2026-04-02 19:40:00', '2026-04-02 20:21:00', 1, 3, 368, 183, 4, 461, '2026-04-03 18:21:00', NULL, NULL),
(462, 'INC-00462', 'Lentidão em estação de trabalho', 'O computador apresenta lentidão constante e travamentos. A operação do setor foi prejudicada durante o período. A equipe de TI iniciou o diagnóstico.', '2026-04-03 20:17:00', '2026-04-03 20:59:00', 4, 1, 135, 365, 11, 462, '2026-04-04 19:59:00', NULL, NULL),
(463, 'INC-00463', 'Falha de disco no servidor de arquivos', 'Foi registrado alerta de falha em disco do servidor. O problema foi classificado conforme impacto e urgência. O caso segue em acompanhamento pela equipe técnica.', '2026-04-04 20:54:00', '2026-04-04 21:37:00', 5, 1, 382, 27, 3, 463, '2026-04-05 21:37:00', NULL, NULL),
(464, 'INC-00464', 'Toner esgotado sem reposição', 'A impressão foi suspensa por falta de suprimento. O atendimento a clientes internos foi parcialmente afetado. O incidente foi escalado para o nível seguinte de suporte.', '2026-04-05 21:31:00', '2026-04-05 22:15:00', 4, 6, 149, 221, 7, 464, '2026-04-06 21:15:00', '2026-04-06 21:15:00', NULL),
(465, 'INC-00465', 'Regra de firewall bloqueando aplicação legítima', 'Uma regra recente bloqueou o tráfego de uma aplicação autorizada. O incidente impactou a produtividade da equipe. Aplicou-se uma solução de contorno enquanto a causa é investigada.', '2026-04-06 22:08:00', '2026-04-06 22:53:00', 2, 4, 416, 397, 4, 465, '2026-04-08 09:53:00', '2026-04-07 23:53:00', '2026-04-08 09:53:00'),
(466, 'INC-00466', 'Falha de conexão com o servidor de banco de dados', 'Aplicações não conseguiram abrir conexão com o banco. Serviços dependentes apresentaram instabilidade. Foram coletados logs e evidências para análise.', '2026-04-07 22:45:00', '2026-04-07 23:31:00', 2, 8, 163, 53, 2, 466, '2026-04-08 10:31:00', NULL, NULL),
(467, 'INC-00467', 'Falha no sistema de URA', 'A central de atendimento não encaminhou as chamadas corretamente. Um grupo de usuários ficou sem acesso ao recurso. O chamado foi direcionado ao suporte responsável.', '2026-04-08 23:22:00', '2026-04-09 00:09:00', 1, 3, 430, 235, 5, 467, '2026-04-09 12:09:00', NULL, NULL),
(468, 'INC-00468', 'Baixa velocidade na rede sem fio', 'A velocidade de conexão ficou abaixo do esperado. Houve risco de indisponibilidade prolongada do serviço. A equipe de TI iniciou o diagnóstico.', '2026-04-09 23:59:00', '2026-04-10 00:47:00', 4, 3, 197, 417, 6, 468, '2026-04-10 13:47:00', NULL, NULL),
(469, 'INC-00469', 'Tentativa de acesso indevido detectada', 'Foram identificadas tentativas repetidas de acesso não autorizado. A ocorrência gerou aumento no volume de chamados. O caso segue em acompanhamento pela equipe técnica.', '2026-04-10 00:36:00', '2026-04-10 01:25:00', 5, 4, 444, 96, 4, 469, '2026-04-10 22:25:00', '2026-04-10 22:25:00', NULL),
(470, 'INC-00470', 'Lentidão no fechamento contábil do ERP', 'Os processos de fechamento demoraram além do esperado. A operação do setor foi prejudicada durante o período. O incidente foi escalado para o nível seguinte de suporte.', '2026-04-11 01:13:00', '2026-04-11 02:03:00', 4, 2, 211, 272, 13, 470, '2026-04-12 06:03:00', '2026-04-12 01:03:00', '2026-04-12 06:03:00'),
(471, 'INC-00471', 'Lentidão de leitura no storage', 'As leituras apresentaram latência acima do normal. O problema foi classificado conforme impacto e urgência. Aplicou-se uma solução de contorno enquanto a causa é investigada.', '2026-04-12 01:50:00', '2026-04-12 02:41:00', 1, 1, 478, 443, 3, 471, '2026-04-12 18:41:00', NULL, NULL),
(472, 'INC-00472', 'Espaço insuficiente no repositório de backup', 'O repositório atingiu o limite e interrompeu novas cópias. O atendimento a clientes internos foi parcialmente afetado. Foram coletados logs e evidências para análise.', '2026-04-13 02:27:00', '2026-04-13 03:19:00', 1, 2, 225, 105, 14, 472, '2026-04-13 20:19:00', NULL, NULL),
(473, 'INC-00473', 'Solicitação de acesso sem atendimento', 'O chamado permaneceu sem retorno da equipe além do prazo de SLA. O incidente impactou a produtividade da equipe. O chamado foi direcionado ao suporte responsável.', '2026-04-14 03:04:00', '2026-04-14 03:57:00', 3, 2, 492, 287, 9, 473, '2026-04-14 21:57:00', NULL, NULL),
(474, 'INC-00474', 'Falha na redefinição de senha', 'O fluxo de redefinição de senha não concluiu para o usuário. Serviços dependentes apresentaram instabilidade. A equipe de TI iniciou o diagnóstico.', '2026-04-15 03:41:00', '2026-04-15 04:35:00', 1, 5, 259, 471, 1, 474, '2026-04-16 11:35:00', '2026-04-16 11:35:00', NULL),
(475, 'INC-00475', 'Falha de sincronização com armazenamento em nuvem', 'Arquivos deixaram de sincronizar entre o ambiente local e a nuvem. Um grupo de usuários ficou sem acesso ao recurso. O caso segue em acompanhamento pela equipe técnica.', '2026-04-16 04:18:00', '2026-04-16 05:13:00', 2, 2, 6, 147, 13, 475, '2026-04-18 00:13:00', '2026-04-17 14:13:00', '2026-04-18 00:13:00'),
(476, 'INC-00476', 'Cabeamento danificado no rack principal', 'Foi identificado cabo com mau contato que causa perda de conexão. Houve risco de indisponibilidade prolongada do serviço. O incidente foi escalado para o nível seguinte de suporte.', '2026-04-17 04:55:00', '2026-04-17 05:51:00', 2, 1, 273, 313, 1, 476, '2026-04-18 02:51:00', NULL, NULL),
(477, 'INC-00477', 'Falha no pipeline de integração contínua', 'O pipeline foi interrompido e impediu a publicação de novas versões. A ocorrência gerou aumento no volume de chamados. Aplicou-se uma solução de contorno enquanto a causa é investigada.', '2026-04-18 05:32:00', '2026-04-18 06:29:00', 5, 2, 40, 495, 13, 477, '2026-04-19 04:29:00', NULL, NULL),
(478, 'INC-00478', 'Caixa de correio cheia', 'Usuários deixaram de receber mensagens por falta de espaço. A operação do setor foi prejudicada durante o período. Foram coletados logs e evidências para análise.', '2026-04-19 06:09:00', '2026-04-19 07:07:00', 4, 7, 287, 157, 13, 478, '2026-04-20 06:07:00', NULL, NULL),
(479, 'INC-00479', 'Indisponibilidade de sistema interno', 'O sistema interno ficou fora do ar durante o expediente. O problema foi classificado conforme impacto e urgência. O chamado foi direcionado ao suporte responsável.', '2026-04-20 06:46:00', '2026-04-20 07:45:00', 4, 2, 54, 346, 13, 479, '2026-04-22 00:45:00', '2026-04-22 00:45:00', NULL),
(480, 'INC-00480', 'Lentidão na rede corporativa', 'Usuários relataram lentidão generalizada ao acessar sistemas internos. O atendimento a clientes internos foi parcialmente afetado. A equipe de TI iniciou o diagnóstico.', '2026-04-21 07:23:00', '2026-04-21 08:23:00', 2, 3, 301, 22, 5, 480, '2026-04-22 04:23:00', '2026-04-21 23:23:00', '2026-04-22 04:23:00'),
(481, 'INC-00481', 'Quedas frequentes na VPN', 'A conexão VPN cai repetidamente durante o expediente. O incidente impactou a produtividade da equipe. O caso segue em acompanhamento pela equipe técnica.', '2026-04-22 08:00:00', '2026-04-22 09:01:00', 1, 3, 68, 183, 4, 481, '2026-04-22 19:01:00', NULL, NULL),
(482, 'INC-00482', 'Tela azul recorrente', 'O equipamento reinicia com tela azul repetidas vezes. Serviços dependentes apresentaram instabilidade. O incidente foi escalado para o nível seguinte de suporte.', '2026-04-23 08:37:00', '2026-04-23 09:39:00', 1, 1, 335, 365, 11, 482, '2026-04-23 20:39:00', NULL, NULL),
(483, 'INC-00483', 'Reinicialização inesperada de servidor', 'O servidor reiniciou sem janela de manutenção programada. Um grupo de usuários ficou sem acesso ao recurso. Aplicou-se uma solução de contorno enquanto a causa é investigada.', '2026-04-24 09:14:00', '2026-04-24 10:17:00', 5, 1, 82, 27, 3, 483, '2026-04-24 22:17:00', NULL, NULL),
(484, 'INC-00484', 'Impressora fora de rede', 'A impressora deixou de responder na rede e não recebe trabalhos. Houve risco de indisponibilidade prolongada do serviço. Foram coletados logs e evidências para análise.', '2026-04-25 09:51:00', '2026-04-25 10:55:00', 4, 6, 349, 221, 7, 484, '2026-04-26 09:55:00', '2026-04-26 09:55:00', NULL),
(485, 'INC-00485', 'Alto uso de sessões no firewall', 'O firewall atingiu o limite de sessões simultâneas. A ocorrência gerou aumento no volume de chamados. O chamado foi direcionado ao suporte responsável.', '2026-04-26 10:28:00', '2026-04-26 11:33:00', 5, 4, 116, 397, 4, 485, '2026-04-27 22:33:00', '2026-04-27 12:33:00', '2026-04-27 22:33:00'),
(486, 'INC-00486', 'Bloqueio de tabela por transação longa', 'Uma transação longa bloqueou operações de outros usuários. A operação do setor foi prejudicada durante o período. A equipe de TI iniciou o diagnóstico.', '2026-04-27 11:05:00', '2026-04-27 12:11:00', 1, 8, 363, 53, 2, 486, '2026-04-28 03:11:00', NULL, NULL),
(487, 'INC-00487', 'Queda do tronco telefônico', 'As ligações externas ficaram indisponíveis. O problema foi classificado conforme impacto e urgência. O caso segue em acompanhamento pela equipe técnica.', '2026-04-28 11:42:00', '2026-04-28 12:49:00', 3, 3, 130, 235, 5, 487, '2026-04-29 04:49:00', NULL, NULL),
(488, 'INC-00488', 'Wi-Fi instável em setor administrativo', 'O sinal sem fio cai com frequência na área administrativa. O atendimento a clientes internos foi parcialmente afetado. O incidente foi escalado para o nível seguinte de suporte.', '2026-04-29 12:19:00', '2026-04-29 13:27:00', 3, 3, 397, 417, 6, 488, '2026-04-30 06:27:00', NULL, NULL),
(489, 'INC-00489', 'Alerta de malware em estação de trabalho', 'O antivírus detectou arquivo malicioso em um equipamento. O incidente impactou a produtividade da equipe. Aplicou-se uma solução de contorno enquanto a causa é investigada.', '2026-04-30 12:56:00', '2026-04-30 14:05:00', 2, 4, 144, 96, 4, 489, '2026-05-01 23:05:00', '2026-05-01 23:05:00', NULL),
(490, 'INC-00490', 'Falha na integração do ERP com o banco', 'A integração deixou de sincronizar dados entre os módulos. Serviços dependentes apresentaram instabilidade. Foram coletados logs e evidências para análise.', '2026-05-01 13:33:00', '2026-05-01 14:43:00', 1, 2, 411, 272, 13, 490, '2026-05-03 06:43:00', '2026-05-03 01:43:00', '2026-05-03 06:43:00'),
(491, 'INC-00491', 'Falha de acesso ao compartilhamento de arquivos', 'Usuários não conseguiram acessar pastas da rede. Um grupo de usuários ficou sem acesso ao recurso. O chamado foi direcionado ao suporte responsável.', '2026-05-02 14:10:00', '2026-05-02 15:21:00', 2, 1, 178, 443, 3, 491, '2026-05-03 11:21:00', NULL, NULL),
(492, 'INC-00492', 'Falha na rotina de backup noturno', 'A rotina de backup não foi concluída dentro da janela prevista. Houve risco de indisponibilidade prolongada do serviço. A equipe de TI iniciou o diagnóstico.', '2026-05-03 14:47:00', '2026-05-03 15:59:00', 5, 2, 425, 105, 14, 492, '2026-05-04 12:59:00', NULL, NULL),
(493, 'INC-00493', 'Fila do service desk acima da capacidade', 'O volume de chamados superou a capacidade de atendimento. A ocorrência gerou aumento no volume de chamados. O caso segue em acompanhamento pela equipe técnica.', '2026-05-04 15:24:00', '2026-05-04 16:37:00', 4, 2, 192, 287, 9, 493, '2026-05-05 14:37:00', NULL, NULL),
(494, 'INC-00494', 'Permissão de acesso incorreta', 'O usuário recebeu acesso além ou aquém do perfil definido. A operação do setor foi prejudicada durante o período. O incidente foi escalado para o nível seguinte de suporte.', '2026-05-05 16:01:00', '2026-05-05 17:15:00', 4, 5, 459, 471, 1, 494, '2026-05-07 00:15:00', '2026-05-07 00:15:00', NULL),
(495, 'INC-00495', 'Erro de permissão em bucket de armazenamento', 'Aplicações receberam erro ao acessar o armazenamento em nuvem. O problema foi classificado conforme impacto e urgência. Aplicou-se uma solução de contorno enquanto a causa é investigada.', '2026-05-06 16:38:00', '2026-05-06 17:53:00', 2, 2, 206, 147, 13, 495, '2026-05-08 12:53:00', '2026-05-08 02:53:00', '2026-05-08 12:53:00'),
(496, 'INC-00496', 'Falha no ar-condicionado da sala de servidores', 'A temperatura da sala técnica subiu acima do limite recomendado. O atendimento a clientes internos foi parcialmente afetado. Foram coletados logs e evidências para análise.', '2026-05-07 17:15:00', '2026-05-07 18:31:00', 2, 1, 473, 313, 1, 496, '2026-05-08 03:31:00', NULL, NULL),
(497, 'INC-00497', 'Erro no deploy em produção', 'A publicação em produção falhou e exigiu reversão. O incidente impactou a produtividade da equipe. O chamado foi direcionado ao suporte responsável.', '2026-05-08 17:52:00', '2026-05-08 19:09:00', 2, 2, 240, 495, 13, 497, '2026-05-09 05:09:00', NULL, NULL),
(498, 'INC-00498', 'E-mails legítimos marcados como spam', 'Mensagens importantes foram desviadas para a quarentena. Serviços dependentes apresentaram instabilidade. A equipe de TI iniciou o diagnóstico.', '2026-05-09 18:29:00', '2026-05-09 19:47:00', 4, 7, 487, 157, 13, 498, '2026-05-10 06:47:00', NULL, NULL),
(499, 'INC-00499', 'Erro após atualização de sistema', 'Uma atualização recente causou comportamento inesperado. Um grupo de usuários ficou sem acesso ao recurso. O caso segue em acompanhamento pela equipe técnica.', '2026-05-10 19:06:00', '2026-05-10 20:25:00', 4, 2, 254, 346, 13, 499, '2026-05-11 21:25:00', '2026-05-11 21:25:00', NULL),
(500, 'INC-00500', 'Queda de conectividade no switch principal', 'Perda de comunicação entre setores foi detectada pelo monitoramento. Houve risco de indisponibilidade prolongada do serviço. O incidente foi escalado para o nível seguinte de suporte.', '2026-05-11 19:43:00', '2026-05-11 21:03:00', 5, 3, 21, 22, 5, 500, '2026-05-13 05:03:00', '2026-05-13 00:03:00', '2026-05-13 05:03:00')
