INSERT INTO ACAO_TRATAMENTO (id_acao, tipo_acao, descricao, data_acao, id_incidente, id_usuario) VALUES
(1, 'Triagem inicial', 'Triagem inicial realizada, incidente classificado e priorizado conforme impacto e urgência (INC-00001 - Falha de acesso ao sistema 1).', '2026-04-01 16:22:00', 1, 28),
(2, 'Coleta de evidências', 'Coletados logs, prints e relatos dos usuários para apoiar o diagnóstico (INC-00002 - Indisponibilidade de serviço 2).', '2026-04-02 05:27:00', 2, 64),
(3, 'Diagnóstico técnico', 'Análise técnica executada para identificar a causa raiz da falha (INC-00003 - Erro de autenticação 3).', '2026-04-03 04:12:00', 3, 109),
(4, 'Reinício de serviço', 'Serviço reiniciado de forma controlada após validação com a equipe responsável (INC-00004 - Lentidão no sistema 4).', '2026-04-04 10:56:00', 4, 145),
(5, 'Escalonamento N2', 'Incidente escalado para o suporte de nível 2 com o histórico de atendimento (INC-00005 - Falha de conexão com servidor 5).', '2026-04-05 09:33:00', 5, 182),
(6, 'Escalonamento N3', 'Incidente escalado para a engenharia de nível 3 para análise aprofundada (INC-00006 - Interrupção de serviço de TI 6).', '2026-04-06 07:44:00', 6, 217),
(7, 'Contato com fornecedor', 'Aberto chamado com o fornecedor e enviadas as evidências para análise (INC-00007 - Erro de processamento 7).', '2026-04-07 16:01:00', 7, 244),
(8, 'Aplicação de patch', 'Correção aplicada em ambiente controlado e monitorada após a execução (INC-00008 - Problema de rede 8).', '2026-04-08 14:04:00', 8, 280),
(9, 'Rollback de mudança', 'Mudança recente revertida para restabelecer o funcionamento do serviço (INC-00009 - Falha em aplicação corporativa 9).', '2026-04-09 11:42:00', 9, 325),
(10, 'Ajuste de configuração', 'Parâmetros de configuração revisados e ajustados conforme a boa prática (INC-00010 - Incidente de infraestrutura 10).', '2026-04-10 08:55:00', 10, 361),
