(481, 'Triagem inicial', 'Triagem inicial realizada, incidente classificado e priorizado conforme impacto e urgência (INC-00481 - Falha de acesso ao sistema 481).', '2026-04-22 15:25:00', 481, 182),
(482, 'Coleta de evidências', 'Coletados logs, prints e relatos dos usuários para apoiar o diagnóstico (INC-00482 - Indisponibilidade de serviço 482).', '2026-04-23 14:22:00', 482, 217),
(483, 'Diagnóstico técnico', 'Análise técnica executada para identificar a causa raiz da falha (INC-00483 - Erro de autenticação 483).', '2026-04-24 12:55:00', 483, 244),
(484, 'Reinício de serviço', 'Serviço reiniciado de forma controlada após validação com a equipe responsável (INC-00484 - Lentidão no sistema 484).', '2026-04-25 20:08:00', 484, 280),
(485, 'Escalonamento N2', 'Incidente escalado para o suporte de nível 2 com o histórico de atendimento (INC-00485 - Falha de conexão com servidor 485).', '2026-04-26 18:33:00', 485, 325),
(486, 'Escalonamento N3', 'Incidente escalado para a engenharia de nível 3 para análise aprofundada (INC-00486 - Interrupção de serviço de TI 486).', '2026-04-27 16:32:00', 486, 361),
(487, 'Contato com fornecedor', 'Aberto chamado com o fornecedor e enviadas as evidências para análise (INC-00487 - Erro de processamento 487).', '2026-04-29 01:17:00', 487, 398),
(488, 'Aplicação de patch', 'Correção aplicada em ambiente controlado e monitorada após a execução (INC-00488 - Problema de rede 488).', '2026-04-29 23:08:00', 488, 433),
(489, 'Rollback de mudança', 'Mudança recente revertida para restabelecer o funcionamento do serviço (INC-00489 - Falha em aplicação corporativa 489).', '2026-04-30 20:33:00', 489, 469),
(490, 'Ajuste de configuração', 'Parâmetros de configuração revisados e ajustados conforme a boa prática (INC-00490 - Incidente de infraestrutura 490).', '2026-05-01 17:34:00', 490, 1),
(491, 'Reset de credenciais', 'Credenciais redefinidas e acesso do usuário validado após a alteração (INC-00491 - Falha de acesso ao sistema 491).', '2026-05-03 04:09:00', 491, 28),
(492, 'Substituição de hardware', 'Componente com defeito substituído e equipamento testado após a troca (INC-00492 - Indisponibilidade de serviço 492).', '2026-05-04 01:00:00', 492, 64),
(493, 'Restauração de backup', 'Dados restaurados a partir do último backup válido e integridade conferida (INC-00493 - Erro de autenticação 493).', '2026-05-04 21:27:00', 493, 109),
(494, 'Bloqueio de ameaça', 'Origem da ameaça bloqueada no firewall e regras de proteção revisadas (INC-00494 - Lentidão no sistema 494).', '2026-05-06 09:34:00', 494, 145),
(495, 'Contenção do incidente', 'Medidas de contenção aplicadas para limitar o impacto sobre os demais serviços (INC-00495 - Falha de conexão com servidor 495).', '2026-05-07 05:53:00', 495, 182),
(496, 'Comunicação aos usuários', 'Usuários afetados informados sobre o status e o prazo estimado de solução (INC-00496 - Interrupção de serviço de TI 496).', '2026-05-07 21:07:00', 496, 217),
(497, 'Workaround aplicado', 'Solução de contorno disponibilizada enquanto a correção definitiva é preparada (INC-00497 - Erro de processamento 497).', '2026-05-09 02:57:00', 497, 244),
(498, 'Teste de validação', 'Testes executados com o usuário para confirmar o restabelecimento do serviço (INC-00498 - Problema de rede 498).', '2026-05-10 02:03:00', 498, 280),
(499, 'Monitoramento pós-correção', 'Serviço monitorado após a correção para garantir estabilidade (INC-00499 - Falha em aplicação corporativa 499).', '2026-05-11 00:44:00', 499, 325),
